contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // run tries to Collect amount `am`. It first ensures this contract had sufficient recorded balance
    // by depositing `am` into c (via Deposit), then calls Collect and records outcomes.
    function run(uint am) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (am)); require(am <= 1000000000000000000000000000000);
        require(address(this).balance >= am);

        // record before-values
        uint beforeBalRecorded = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint beforeThis = address(this).balance;
        uint beforeC = address(c).balance;

        // Ensure the contract's recorded balance is at least beforeBalRecorded + am by depositing am
        // Deposit must be a top-level call that can change c's state
        c.Deposit{value: am}(); if (__ESBMC_reverted()) return;

        // after deposit readings
        uint afterDepositRecorded = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint afterDepositThis = address(this).balance;
        uint afterDepositC = address(c).balance;

        // Now attempt to Collect `am`. Catch whether it reverted.
        bool reverted;
        c.Collect(am); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // readings after collect attempt
        uint finalRecorded = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint finalThis = address(this).balance;
        uint finalC = address(c).balance;

        // General property: if Collect did not revert, then the recorded balance decreased by exactly am,
        // and this contract's ether balance increased by exactly am and c's balance decreased by exactly am.
        assert(reverted || (afterDepositRecorded >= am && finalRecorded + am == afterDepositRecorded
               && finalThis == afterDepositThis + am
               && finalC + am == afterDepositC));
    }

    // allow receiving Ether if c sends funds during Collect
    receive() external payable {}
}

