pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 am) internal {
        am = bound(am, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= am);
        uint256 beforeBalRecorded;
        try c.balances(address(this)) returns (uint256 __r) { beforeBalRecorded = __r; } catch { return; }
        uint beforeThis = address(this).balance;
        uint beforeC = address(c).balance;
        try c.Deposit{value: am}() {} catch { return; }
        uint256 afterDepositRecorded;
        try c.balances(address(this)) returns (uint256 __r) { afterDepositRecorded = __r; } catch { return; }
        uint afterDepositThis = address(this).balance;
        uint afterDepositC = address(c).balance;
        bool reverted;
        try c.Collect(am) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 finalRecorded;
        try c.balances(address(this)) returns (uint256 __r) { finalRecorded = __r; } catch { return; }
        uint finalThis = address(this).balance;
        uint finalC = address(c).balance;
        assertTrue(reverted || (afterDepositRecorded >= am && finalRecorded + am == afterDepositRecorded
               && finalThis == afterDepositThis + am
               && finalC + am == afterDepositC));
    }

    function testFuzz_run(uint256 am) public {
        _run(am);
    }

    receive() external payable {}
}
